style.css:
@-moz-document url("https://waikato.ivanticloud.com/") {
#app-frame-logo[id^="ext-comp-"], .x-logo-area, .headerbar-app-logo {
    background-image: url(data:image/svg+xml;base64,) !important;
    background-size: 60px !important;
}
#app-frame-logo[id^="ext-comp-"]::after, .x-logo-area::after, .headerbar-app-logo::after {
    content:'Te Kuhukuhu Rārangi';
    font-family:"Mansalva";
    font-size: 1.25rem;
    line-height: 2.25;
    margin-left: 60px;
    text-transform: uppercase;
}
#app-frame-logo div {
    transform: scale(1);
}
.flex-list-item-custom span {
    overflow: auto;
}
.x-tab-panel.x-frs-flex-portlet.x-frs-object-workspace-form-tabs {
    overflow: auto;
    width: 94vw;
}
@font-face {
    font-family:'Mansalva';
    font-style: normal;
    font-weight: 400;
    /* font-display: swap; */
    src: local('Mansalva Regular'), local('Mansalva-Regular'), url(https://fonts.gstatic.com/s/mansalva/v1/aWB4m0aacbtDfvq5NKliKY_NdDBh.woff2) format('woff2');
}

#app-frame-user-card-photo {
background-image: none !important;
}
